use vstd::prelude::*;

verus! {
    // Specification for the recursive count function
    spec fn count_recursive(prefix: Vec<char>) -> u64
        decreases prefix.len(),
    {
        if prefix.len() == 0 {
            0
        } else {
            let x = prefix[prefix.len() - 1];
            let rest = prefix[..prefix.len() - 1].to_vec();
            count_recursive(rest) + (if is_uppercase(x) { 1 } else { 0 })
        }
    }

    // Helper function to check if a character is an uppercase ASCII letter
    spec fn is_uppercase(c: char) -> bool {
        65 <= c as u32 && c as u32 <= 90
    }

    // Main function to count uppercase letters in the input vector
    fn count_uppercase(text: &Vec<char>) -> u64
        ensures
            0 <= result <= text.len() as u64,
            result == count_recursive(text.clone()),
    {
        let mut count: u64 = 0;
        let mut idx: usize = 0;
        let len = text.len();

        while idx < len
            invariant
                0 <= idx <= len,
                count == count_recursive(text[..idx].to_vec()),
                count <= idx as u64,
            decreases len - idx,
        {
            let c = text[idx];
            if is_uppercase(c) {
                count = count + 1;
            }
            idx = idx + 1;
        }
        count
    }
}

